def target_iter(target, scope):
    try:
        return iter(target)
    except TypeError:
        raise scope[glom].UnregisteredTarget(
            f"target {target!r} is not iterable", target, scope
        )

def GROUP(target, spec, scope):
    return scope[glom](target, spec, scope)

def glomit(self, target, scope):
    if scope[MODE] is not GROUP:
        raise BadSpec("Limit() only valid in Group mode")
    tree = scope[ACC_TREE]
    if self not in tree:
        tree[self] = [0, {}]
    scope[ACC_TREE] = tree[self][1]
    tree[self][0] += 1
    if tree[self][0] > self.n:
        return STOP
    return scope[glom](target, self.subspec, scope)
